function reminderEmail(event,config,now=Date.now()) {
  const p=event?.extendedProperties?.private;
  const uuid=x=>typeof x==='string'&&/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i.test(x);
  if(event?.status!=='confirmed'||!uuid(p?.sweetwaterRequestId)||event.id!=='5a'+p.sweetwaterRequestId.replaceAll('-','')||typeof p.sweetwaterName!=='string'||typeof p.sweetwaterEmail!=='string'||! /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.sweetwaterEmail))return null;
  const start=Date.parse(event.start?.dateTime),end=Date.parse(event.end?.dateTime),remaining=start-now;
  // The entire retry window fits inside Resend's 24-hour idempotency retention.
  if(!Number.isFinite(start)||end-start!==20*60000||remaining>24*3600000||remaining<=23*3600000)return null;
  const when=new Intl.DateTimeFormat('en-US',{timeZone:config.timeZone,weekday:'long',month:'long',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(start));
  const text=`Hi ${p.sweetwaterName},

A quick reminder: your free 20-minute call with Sweetwater Technology is coming up.

${when}
Time zone: ${config.timeZone}

No preparation is needed. We'll talk about where work gets stuck and what might make the biggest difference. Call details are sent separately; reply here if you need them.

Need to cancel or reschedule? Use the private link in your confirmation email, or reply to this email for help.

Clint and Sheree
Sweetwater Technology
https://sweetwater.technology

Booking reference: ${event.id}`;
  const escape=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
  const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Your Sweetwater call is coming up</title></head><body style="margin:0;background:#f1f5fb;color:#142035;font-family:Arial,sans-serif"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px"><table role="presentation" width="100%" style="max-width:600px;background:#fff;border-radius:16px" cellpadding="0" cellspacing="0"><tr><td style="background:#1556e8;color:#fff;padding:28px;border-radius:16px 16px 0 0"><p>SWEETWATER TECHNOLOGY</p><h1 style="font-size:28px">Your call is coming up.</h1></td></tr><tr><td style="padding:28px;font-size:16px;line-height:1.6"><p>Hi ${escape(p.sweetwaterName)},</p><p>A quick reminder about your free 20-minute call.</p><p style="padding:18px;background:#eef4ff;border-radius:10px"><strong>${escape(when)}</strong><br>Time zone: ${escape(config.timeZone)}</p><p>No preparation is needed. We'll talk about where work gets stuck and what might make the biggest difference.</p><p>Call details are sent separately; reply here if you need them.</p><p>Need to cancel or reschedule? Use the private link in your confirmation email, or reply to this email for help.</p><p>Clint and Sheree<br><a href="https://sweetwater.technology">Sweetwater Technology</a></p><p style="font-size:12px;color:#536075">Booking reference: ${escape(event.id)}</p></td></tr></table></td></tr></table></body></html>`;
  return {key:'sweetwater-reminder/'+event.id+'/'+start,payload:{from:'Sweetwater Technology <team@sweetwater.technology>',to:[p.sweetwaterEmail],reply_to:'team@sweetwater.technology',subject:'Reminder: your Sweetwater call is coming up',html,text}};
}
